<script setup lang="ts">import {ref,onMounted,computed,watch} from 'vue';import {useRoute} from 'vue-router';import {useLab} from '../stores/laboratory';import {calibrate} from '../api/runs';import {useTask} from '../hooks/useTask';import {usePolling} from '../hooks/usePolling';import PageTitle from '../components/common/PageTitle.vue';import ErrorNotice from '../components/common/ErrorNotice.vue';import StatusBadge from '../components/common/StatusBadge.vue';import EmptyState from '../components/common/EmptyState.vue';import MethodSummary from '../components/MethodSummary.vue';import AgreementPlot from '../components/AgreementPlot.vue';import {number} from '../utils/format';const lab=useLab(),route=useRoute(),selected=ref(Number(route.query.run)||0),value=ref(50),estimate=ref<number>(),{error,perform}=useTask();const run=computed(()=>lab.runs.find(r=>r.id===selected.value));onMounted(()=>perform(async()=>{await lab.load();if(!selected.value)selected.value=lab.runs[0]?.id||0;}));watch(()=>route.query.run,v=>{if(v)selected.value=Number(v);});watch(selected,()=>{estimate.value=undefined;});usePolling(async()=>{if(run.value&&['queued','running'].includes(run.value.status))await lab.load();});function inverse(){estimate.value=undefined;perform(async()=>{const r=await calibrate(selected.value,value.value);estimate.value=r.reference_estimate;});}</script><template><PageTitle index="04" title="从拟合关系，读到测量边界" text="回归描述校准关系；Bland–Altman检查差值。两张图回答不同问题。"><RouterLink class="outline" :to="'/qualifications?run='+selected">记录资格用途 ↗</RouterLink></PageTitle><ErrorNotice :message="error" @retry="perform(lab.load)"/><div class="run-selector"><label>研究档案<select v-model="selected"><option v-for="r in lab.runs" :key="r.id" :value="r.id">#{{r.id}} {{r.name}}</option></select></label><StatusBadge v-if="run" :status="run.status"/></div><template v-if="run?.status==='completed'"><div class="results-charts"><AgreementPlot :result="run.result" kind="deming"/><AgreementPlot :result="run.result" kind="ba"/></div><div class="results-details"><MethodSummary :run="run"/><section class="interval-table"><h2>参数与界限的不确定性</h2><table><thead><tr><th>估计量</th><th>点估计</th><th>95% bootstrap CI</th></tr></thead><tbody><tr v-for="row in [['截距',run.result.intercept,run.result.intercept_ci],['斜率',run.result.slope,run.result.slope_ci],['平均偏差',run.result.bias,run.result.bias_ci],['一致性下界',run.result.loa_lower,run.result.lower_ci],['一致性上界',run.result.loa_upper,run.result.upper_ci]]" :key="String(row[0])"><td>{{row[0]}}</td><td>{{number(row[1] as number,4)}}</td><td>{{(row[2] as number[])?.map(v=>number(v,4)).join(' — ')}}</td></tr></tbody></table><p class="input-note">成功重采样 {{run.result.bootstrap_success}} 次 / 退化 {{run.result.bootstrap_failed}} 次 / seed {{run.result.bootstrap_seed}}。相关系数 r={{number(run.result.correlation,5)}} 仅描述共同变化。</p></section><form class="calibration-form" @submit.prevent="inverse"><p class="eyebrow">INVERSE CALIBRATION / 研究内</p><h2>候选读数 → 参考估计</h2><label>候选仪器 Y / %<input v-model.number="value" type="number" min="0" max="100" step=".001" required></label><button class="outline">计算 (Y−a) / b →</button><p v-if="estimate!==undefined" class="inverse-answer" role="status">{{number(estimate,4)}} <small>参考估计 / %</small></p><p class="input-note">本次X范围 {{run.result.x_range?.map(v=>number(v,2)).join('—')}}%；Y范围 {{run.result.y_range?.map(v=>number(v,2)).join('—')}}%。超出任一范围拒绝外推；点估计不含个体预测误差。</p></form></div><p class="fingerprint">INPUT SHA256 / {{run.result.fingerprint}}</p></template><EmptyState v-else :title="run?.status==='failed'?'研究未完成':'等待配对计算结果'" :text="run?.error||'运行状态会自动刷新。请先建立研究，或从研究目录选择一份已归档记录。'"/></template>
